/**
 * Generates sql/003_seed_mvp2.sql from the plan engine's catalogue so the
 * database can never disagree with the generator about exercise names or
 * recipes. Run after editing engine/catalog.ts:  npm run gen:seed
 */
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { RECIPES, allGeneratorExercises, exerciseMeta } from "../src/modules/planning/engine/index.js";

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;
const arr = (xs: string[]) => `ARRAY[${xs.map(q).join(",")}]::text[]`;

const lines: string[] = [
  "-- GENERATED by scripts/gen-seed.ts from src/modules/planning/engine/catalog.ts. Do not edit by hand.",
  "-- Idempotent: safe to re-run.",
  "",
  "-- Exercises the plan generator can prescribe (matched case-insensitively on name).",
];
for (const name of allGeneratorExercises()) {
  const m = exerciseMeta(name);
  lines.push(
    `INSERT INTO tracking.exercises (name, muscle_group, equipment, pattern) SELECT ${q(name)}, ${q(m.muscleGroup)}::tracking.muscle_group, ${q(m.equipment)}, ${m.pattern ? q(m.pattern) : "NULL"} ` +
      `WHERE NOT EXISTS (SELECT 1 FROM tracking.exercises WHERE lower(name) = lower(${q(name)}) AND NOT is_custom);`,
  );
  lines.push(`UPDATE tracking.exercises SET pattern = ${m.pattern ? q(m.pattern) : "NULL"} WHERE lower(name) = lower(${q(name)}) AND NOT is_custom;`);
}
lines.push("", "-- Local recipe layer (spec §9.4). Placeholder nutrition values pending the vendor decision.");
for (const r of RECIPES) {
  lines.push(
    `INSERT INTO nutrition.recipes (key, dish, name, slot, kcal, protein_g, carbs_g, fat_g, diets, allergens, portion_guide, is_local) VALUES ` +
      `(${q(r.key)}, ${q(r.dish)}, ${q(r.name)}, ${q(r.slot)}, ${r.kcal}, ${r.proteinG}, ${r.carbsG}, ${r.fatG}, ${arr(r.diets)}, ${arr(r.allergens)}, ${q(r.portionGuide)}, ${r.isLocal}) ` +
      `ON CONFLICT (key) DO UPDATE SET dish = EXCLUDED.dish, name = EXCLUDED.name, slot = EXCLUDED.slot, kcal = EXCLUDED.kcal, protein_g = EXCLUDED.protein_g, ` +
      `carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, diets = EXCLUDED.diets, allergens = EXCLUDED.allergens, portion_guide = EXCLUDED.portion_guide, is_local = EXCLUDED.is_local;`,
  );
}
const out = fileURLToPath(new URL("../sql/003_seed_mvp2.sql", import.meta.url));
writeFileSync(out, lines.join("\n") + "\n");
console.log(`Wrote ${out}`);
